const input = $input.first().json;
const rawCnpj = String(input.cnpj ?? '');
const digits = rawCnpj.replace(/\D/g, '');

function formatCnpj(value) {
  if (!/^\d{14}$/.test(value)) return value;
  return value.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})$/, '$1.$2.$3/$4-$5');
}

function isValidCnpj(cnpj) {
  if (!/^\d{14}$/.test(cnpj)) return false;
  if (/^(\d)\1{13}$/.test(cnpj)) return false;

  const calcDigit = (base) => {
    let sum = 0;
    let weight = base.length - 7;

    for (let i = 0; i < base.length; i++) {
      sum += Number(base[i]) * weight--;
      if (weight < 2) weight = 9;
    }

    const rest = sum % 11;
    return rest < 2 ? 0 : 11 - rest;
  };

  const base12 = cnpj.slice(0, 12);
  const digit1 = calcDigit(base12);
  const digit2 = calcDigit(base12 + String(digit1));

  return cnpj === base12 + String(digit1) + String(digit2);
}

const cnpjValido = isValidCnpj(digits);

return [{
  json: {
    ...input,
    cnpjLimpo: digits,
    cnpjFormatado: formatCnpj(digits),
    cnpjValido,
    mensagemValidacao: cnpjValido ? 'CNPJ valido' : 'CNPJ invalido'
  }
}];

const api = $input.first().json;
const cadastro = $('Normalizar CNPJ').item.json;

return [{
  json: {
    status: 'ok',
    mensagem: 'Cadastro validado com sucesso',
    cnpj: cadastro.cnpjFormatado,
    cnpjLimpo: cadastro.cnpjLimpo,
    razaoSocial: api.razao_social ?? api.razaoSocial ?? '',
    nomeFantasia: api.nome_fantasia ?? '',
    situacaoCadastral: api.descricao_situacao_cadastral ?? '',
    municipio: api.municipio ?? '',
    uf: api.uf ?? '',
    porte: api.porte ?? '',
    cnaePrincipal: api.cnae_fiscal_descricao ?? '',
    inicioAtividade: api.data_inicio_atividade ?? ''
  }
}];

const cadastro = $('Normalizar CNPJ').item.json;

return [{
  json: {
    status: 'erro',
    mensagem: 'CNPJ invalido. Verifique os 14 digitos e tente novamente.',
    cnpj: cadastro.cnpjFormatado || cadastro.cnpj || '',
    cnpjLimpo: cadastro.cnpjLimpo || ''
  }
}];
